 \"COOKIE SETTINGS\"\n    - button \"Cookie and Ad Preferences\"\n    - link \"California ab 1305 disclosure statement\":\n      - /url: https://www.inditex.com/itxcomweb/api/media/d6d06b5c-4a2f-431d-915f-ce8ca9e95181/Sustainabilityreport2024.pdf?t=1756810205890#page=58\n  - navigation \"Breadcrumbs Trail\":\n    - list:\n      - link \"ZARA\":\n        - /url: https://www.zara.com/\n      - text: /\n      - link \"REGULAR FIT DENIM WESTERN SHIRT\":\n        - /url: \"#main\"\n  - list \"Available stores\":\n    - button \"United States\"\n  - list \"Available languages\":\n    - listitem: English|\n    - link \"Español\":\n      - /url: /us/es/camisa-western-denim-regular-fit-p06987370.html\n  - generic: © All rights reserved\n- dialog \"Composition & care\":\n  - button \"Close\" [active]:\n  - generic: COMPOSITION & CARE\n  - generic: COMPOSITION\n  - generic: OUTER SHELL\n  - generic: 100% cotton\n  - generic: \"Which has at least:\"\n  - generic: OUTER SHELL\n  - generic: 30% RCS-certified recycled cotton\n  - generic: 70% OCS certified organically grown cotton\n  - generic: Certified materials\n  - generic: RCS CERTIFIED RECYCLED COTTON\n  - generic: This fiber is made from recycled cotton textile waste. Using recycled materials helps limit the consumption of raw materials. It is certified to the Recycled Claim Standard (RCS), which verifies the recycled content and tracks it from source to final product.\n  - generic: Certified by Intertek 193341\n  - link \"More information\":\n    - /url: https://www.zara.com/us/en/sostenibilidad-web-verde-l1453.html?v1=2247135\n    - generic: More information\n  - generic: OCS CERTIFIED ORGANICALLY GROWN COTTON\n  - generic: This fiber is produced without using artificial fertilizers or pesticides and is grown from seeds that have not been genetically modified. We are currently working with the Organic Content Standard (OCS) that supervises the process from the source to the end product.\n  - generic: Certified by Intertek 193341\n  - link \"More information\":\n    - /url: https://www.zara.com/us/en/sostenibilidad-web-verde-l1453.html?v1=2247135\n    - generic: More information\n  - generic: CARE\n  - generic: Take care of your clothes to lengthen their useful life.\n  - text: Wash your garments only when needed. Washing processes damage textiles over time.\n  - link \"Clothing care guide\":\n    - /url: https://www.zara.com/us/en/sustainability-clothing-care-l3129.html?v1=1596204\n  - list:\n    - generic: Hand wash max 30ºC/86ºF\n    - generic: Do not use bleach / whitener\n    - generic: Iron maximum 110ºC/230ºF\n    - generic: Tetrachloroethylene Dry Clean\n    - generic: Low temperature dryer may be used\n  - generic: ORIGIN\n  - generic: Made in Bangladesh", "product_url": "https://www.zara.com/us/en/regular-fit-denim-western-shirt-p06987370.html", "category_urls": ["https://www.zara.com/us/en/man-shirts-l737.html"], "department": "Man", "base_price": "59.90", "currency": "USD", "colors": ["Charcoal", "Khaki", "Mid-blue", "Striped"], "sizes": ["L", "M", "S", "XL"], "source_last_seen_at": "2026-09-06T04:23:30.470Z", "status": "observed", "evidence_file": "data\\raw\\zara\\06987370.json", "classification": "PUBLICLY OBSERVED", "completeness": "captured JSON-LD only; not guaranteed exhaustive"}'::jsonb) ON CONFLICT(product_id) DO UPDATE SET document=EXCLUDED.document;
